// Type: DeliveryReason.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum DeliveryReason {
    Unreachable,
    RefusedByTarget,
    TimedOut,
    Broken,
    TooLarge,
    Missing,
    Busy,
    Unavailable,
    Cancelled,
    Unknown,
}

// Record: DeliveryReason.
impl Record for DeliveryReason {
    type Limits = Limits;
    const TAIL: Path = paths::DELIVERY_REASON_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 47)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 47)?.decoded)
    }

    fn write(&self, _limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Unreachable => field::put(out, &[0], paths::DELIVERY_REASON_TAG),
            Self::RefusedByTarget => field::put(out, &[1], paths::DELIVERY_REASON_TAG),
            Self::TimedOut => field::put(out, &[2], paths::DELIVERY_REASON_TAG),
            Self::Broken => field::put(out, &[3], paths::DELIVERY_REASON_TAG),
            Self::TooLarge => field::put(out, &[4], paths::DELIVERY_REASON_TAG),
            Self::Missing => field::put(out, &[5], paths::DELIVERY_REASON_TAG),
            Self::Busy => field::put(out, &[6], paths::DELIVERY_REASON_TAG),
            Self::Unavailable => field::put(out, &[7], paths::DELIVERY_REASON_TAG),
            Self::Cancelled => field::put(out, &[8], paths::DELIVERY_REASON_TAG),
            Self::Unknown => field::put(out, &[9], paths::DELIVERY_REASON_TAG),
        }
    }

    fn read(_limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::DELIVERY_REASON_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Unreachable),
            1 => Ok(Self::RefusedByTarget),
            2 => Ok(Self::TimedOut),
            3 => Ok(Self::Broken),
            4 => Ok(Self::TooLarge),
            5 => Ok(Self::Missing),
            6 => Ok(Self::Busy),
            7 => Ok(Self::Unavailable),
            8 => Ok(Self::Cancelled),
            9 => Ok(Self::Unknown),
            10..=u8::MAX => Err(Problem { path: paths::DELIVERY_REASON_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

