// Type: Answer.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Answer {
    Delivered(Delivered),
    Nothing,
    Refused(DeliveryRefusal),
    Failed(DeliveryFailure),
    Stale,
}

// Record: Answer.
impl Record for Answer {
    type Limits = Limits;
    const TAIL: Path = paths::ANSWER_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 54)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 54)?.decoded)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Delivered(value) => { field::put(out, &[0], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Nothing => field::put(out, &[1], paths::ANSWER_TAG),
            Self::Refused(value) => { field::put(out, &[2], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Failed(value) => { field::put(out, &[3], paths::ANSWER_TAG)?; value.write(limits, out) },
            Self::Stale => field::put(out, &[4], paths::ANSWER_TAG),
        }
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::ANSWER_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Delivered(Delivered::read(limits, reader)?)),
            1 => Ok(Self::Nothing),
            2 => Ok(Self::Refused(DeliveryRefusal::read(limits, reader)?)),
            3 => Ok(Self::Failed(DeliveryFailure::read(limits, reader)?)),
            4 => Ok(Self::Stale),
            5..=u8::MAX => Err(Problem { path: paths::ANSWER_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

