// Type: Delivery.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct Delivery {
    pub name: CallName,
    pub state: DeliveryState,
    pub landed: List<Receipt>,
}

// Record: Delivery.
impl Record for Delivery {
    type Limits = Limits;
    const TAIL: Path = paths::DELIVERY_TAIL;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 58)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 58)?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        field::put(out, &VERSION.to_be_bytes(), paths::DELIVERY_VERSION)?;
        field::write(field::Nested, &self.name, limits, out, paths::DELIVERY_NAME)?;
        field::write(field::Nested, &self.state, limits, out, paths::DELIVERY_STATE)?;
        field::write(field::Sequence { limit: limits.delivery_landed.min(CEILINGS.delivery_landed), minimum: 8, item: field::Nested }, &self.landed, limits, out, paths::DELIVERY_LANDED)?;
        Ok(())
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        field::version(reader, VERSION, paths::DELIVERY_VERSION)?;
        Ok(Self {
            name: field::read(field::Nested, limits, reader, paths::DELIVERY_NAME)?,
            state: field::read(field::Nested, limits, reader, paths::DELIVERY_STATE)?,
            landed: field::read(field::Sequence { limit: limits.delivery_landed.min(CEILINGS.delivery_landed), minimum: 8, item: field::Nested }, limits, reader, paths::DELIVERY_LANDED)?,
        })
    }
}

